mapper.select:
SELECT id, vehicle_id, expires_at
FROM connect_code
WHERE kind = 'QR' AND code_hash = #{codeHash}

mapper.update:
UPDATE passenger
SET push_endpoint = #{endpoint}, push_p256dh = #{p256dh}, push_auth = #{auth}, push_updated_at = #{now}
WHERE id = #{passengerId}

UPDATE passenger
SET push_endpoint = NULL, push_p256dh = NULL, push_auth = NULL, push_updated_at = NULL
WHERE id = #{passengerId}

mapper.select:
SELECT m.id, m.call_id, m.passenger_id, p.nickname, p.revoked_at IS NOT NULL AS revoked,
	m.kind, m.quick_code, m.body, m.sent_at
FROM departure_message m
JOIN departure_call c ON c.id = m.call_id
LEFT JOIN passenger p ON p.id = m.passenger_id
WHERE c.vehicle_id = #{vehicleId}
	AND m.sent_at >= #{since}
	AND m.id < #{before}
ORDER BY m.id DESC
LIMIT #{limit}
